//! WebP interoperability fixture produced before the gamut-webp migration.
//!
//! The bytes were encoded from a 1×1 RGB image by rawshift at commit
//! `e00a0bf`, using its `libwebp-sys 0.14.2` codec/mux wrapper in lossless
//! mode. The container carries EXIF, sRGB ICC, and XMP chunks. Keeping the
//! fixture as hex makes its external-backend provenance reviewable without
//! adding an opaque binary to the repository.

const LIBWEBP_METADATA_WEBP_HEX: &str = "";

pub fn libwebp_metadata_webp() -> Vec<u8> {
    LIBWEBP_METADATA_WEBP_HEX
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let digit = |byte: u8| match byte {
                b'0'..=b'9' => byte - b'0',
                b'a'..=b'f' => byte - b'a' + 10,
                _ => panic!("invalid fixture hex"),
            };
            (digit(pair[0]) << 4) | digit(pair[1])
        })
        .collect()
}
